&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; magie bardique, &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#REPRESENTATIONBARDIQUE&quot; title=&quot;Le barde&quot;&gt;repr&#233;sentation bardique&lt;/a&gt; 40 rounds/jour (action rapide ; &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentations.html#CONTRECHANT&quot; title=&quot;Les repr&#233;sentations bardiques du barde&quot;&gt;contrechant&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentations.html#DISTRACTION&quot; title=&quot;Les repr&#233;sentations bardiques du barde&quot;&gt;distraction&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentations.html#FASCINATION&quot; title=&quot;Les repr&#233;sentations bardiques du barde&quot;&gt;fascination&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentations.html#INSPIRATIONVAILLANTE&quot; title=&quot;Les repr&#233;sentations bardiques du barde&quot;&gt;inspiration vaillante +4&lt;/a&gt;)
